    internal InnerHyperParameterTuningJobParameterRangesFactory ParameterRangesFactory { get; set; }

    internal InnerHyperParameterTuningJobTuningJobCompletionCriteriaFactory TuningJobCompletionCriteriaFactory { get; set; }

    protected override Humidifier.SageMaker.HyperParameterTuningJobTypes.HyperParameterTuningJobConfig Create()
    {
        var hyperParameterTuningJobConfigResult = CreateHyperParameterTuningJobConfig();
        factoryAction?.Invoke(hyperParameterTuningJobConfigResult);

        return hyperParameterTuningJobConfigResult;
    }

    private Humidifier.SageMaker.HyperParameterTuningJobTypes.HyperParameterTuningJobConfig CreateHyperParameterTuningJobConfig()
    {
        var hyperParameterTuningJobConfigResult = new Humidifier.SageMaker.HyperParameterTuningJobTypes.HyperParameterTuningJobConfig();

        return hyperParameterTuningJobConfigResult;
    }
    public override void CreateChildren(Humidifier.SageMaker.HyperParameterTuningJobTypes.HyperParameterTuningJobConfig result)
    {
        base.CreateChildren(result);

        result.StrategyConfig ??= StrategyConfigFactory?.Build();
        result.HyperParameterTuningJobObjective ??= HyperParameterTuningJobObjectiveFactory?.Build();
        result.ResourceLimits ??= ResourceLimitsFactory?.Build();
        result.ParameterRanges ??= ParameterRangesFactory?.Build();
        result.TuningJobCompletionCriteria ??= TuningJobCompletionCriteriaFactory?.Build();
    }

} // End Of Class

